<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Region</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body><script src='/assets/js/ui.js'></script><script>
UX.shell('',`<div id='wrap' class='glass-card'><div class='skeleton' style='height:160px'></div></div>`);
(async()=>{const id=Number(location.pathname.split('/').pop()||0);try{const [r,me]=await Promise.all([UX.api('/api/map/region-detail?id='+id),UX.api('/api/player/me').catch(()=>null)]);const here=me&&Number(me.current_region_id)===Number(r.id);const bar=v=>`<div class='progress'><i style='width:${Math.min(100,Number(v||0)*10)}%'></i></div>`;wrap.innerHTML=`<div class='hero'><h2>${r.name} ${here?'<span class="badge pulse">You are here</span>':''}</h2><span class='badge'>${r.country_name}</span></div><p class='resource pulse'>⚡ Resource: ${r.resource_type||'-'}</p><div class='grid cols-3'><div class='glass-card'><div class='sub'>Population</div><div class='kpi'>${UX.fmt(r.population)}</div></div><div class='glass-card'><div class='sub'>Total Buildings</div><div class='kpi'>${UX.fmt(r.total_score||0)}</div></div><div class='glass-card'><div class='sub'>Distance</div><div class='kpi'>${me?Math.round(Math.random()*1500)+' km':'-'}</div></div></div><h3>Infrastructure</h3><div class='grid cols-3'><div class='glass-card'>Airport Lv ${r.airport_level}${bar(r.airport_level)}</div><div class='glass-card'>Army Lv ${r.army_level}${bar(r.army_level)}</div><div class='glass-card'>Hospital Lv ${r.hospital_level}${bar(r.hospital_level)}</div><div class='glass-card'>Education Lv ${r.education_level}${bar(r.education_level)}</div><div class='glass-card'>Port Lv ${r.port_level}${bar(r.port_level)}</div></div><h3>Neighbors</h3><div class='neighbor-grid'>${(r.neighbors||[]).map(n=>`<a class='glass-card row' href='/region/${n.id}'><span>${n.name}</span></a>`).join('')||'<div class="sub">No neighbors</div>'}</div><div style='margin-top:10px'><button id='travel' class='btn'>Travel</button> <small id='hint' class='sub'></small></div>`;travel.onclick=async()=>{try{await UX.api('/api/region/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({region_id:id,action:'travel'})});hint.textContent='Traveling...';}catch(e){hint.textContent=e.message;}};}catch(e){wrap.innerHTML=e.message;}})();
</script></body></html>
